 page+=f'<article><h2>{html.escape(r["composer"])} — {html.escape(r["title"])}</h2><p>{html.escape(r["credit"])}</p><p><a href="{html.escape(r["sourceUrl"],quote=True)}">Source de l’enregistrement</a> · '
